import os
import unicodedata
from flask import Flask, request, abort, send_file
import hashlib
import secrets

app = Flask(__name__)

BASE_DIR = '/var/www/uploads'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc'}

def generate_csrf_token():
    return secrets.token_hex(32)

def validate_extension(filename):
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return False
    return True

def sanitize_filename(filename):
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Strip leading/trailing whitespace
    filename = filename.strip()
    # Reject empty filenames
    if not filename:
        return None
    return filename

def is_path_safe(filepath, base_directory):
    """Check that the resolved path is within the base directory."""
    # Resolve to absolute path
    abs_path = os.path.abspath(filepath)
    abs_base = os.path.abspath(base_directory)
    # Ensure the path starts with the base directory
    if not abs_path.startswith(abs_base + os.sep) and abs_path != abs_base:
        return False
    return True

def normalize_unicode(text):
    """Normalize unicode to canonical form for consistent handling."""
    return unicodedata.normalize('NFKC', text)

@app.route('/download', methods=['GET'])
def download_file():
    filename = request.args.get('filename', '')

    if not filename:
        abort(400, 'Filename required')

    # Step 1: Basic sanitization
    filename = sanitize_filename(filename)
    if filename is None:
        abort(400, 'Invalid filename')

    # Step 2: Normalize unicode BEFORE security checks
    filename = normalize_unicode(filename)

    # Step 3: Validate extension
    if not validate_extension(filename):
        abort(403, 'File type not allowed')

    # Step 4: Security check - verify path is safe
    filepath = os.path.join(BASE_DIR, filename)
    if not is_path_safe(filepath, BASE_DIR):
        abort(403, 'Access denied: path traversal detected')

    # Step 5: Serve the file
    if not os.path.isfile(filepath):
        abort(404, 'File not found')

    return send_file(filepath)

@app.route('/list', methods=['GET'])
def list_files():
    try:
        files = os.listdir(BASE_DIR)
        safe_files = [f for f in files if validate_extension(f)]
        return {'files': safe_files}
    except OSError:
        abort(500, 'Unable to list files')

if __name__ == '__main__':
    os.makedirs(BASE_DIR, exist_ok=True)
    app.run(host='127.0.0.1', port=8080, debug=False)
